create or replace function opening_date_hard_lock()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare d date;sid bigint;begin d:=case tg_table_name when'transaction'then new.tran_date when'invoice'then new.invoice_date when'supplier_invoice'then new.invoice_date when'purchase_document'then new.document_date when'sales_document'then new.document_date end;sid:=new.subsidiary_id;if exists(select 1 from opening_balance_runs where subsidiary_id=sid and status='POSTED'and d<=opening_date)then raise exception'La fecha % está bloqueada por la apertura contable. Registre el movimiento después de la fecha de apertura.',d;end if;return new;end$$;
drop trigger if exists opening_lock_transaction on "transaction";create trigger opening_lock_transaction before insert or update of tran_date on "transaction"for each row execute function opening_date_hard_lock();
drop trigger if exists opening_lock_invoice on invoice;create trigger opening_lock_invoice before insert or update of invoice_date on invoice for each row execute function opening_date_hard_lock();
drop trigger if exists opening_lock_supplier_invoice on supplier_invoice;create trigger opening_lock_supplier_invoice before insert or update of invoice_date on supplier_invoice for each row execute function opening_date_hard_lock();
drop trigger if exists opening_lock_purchase_document on purchase_document;create trigger opening_lock_purchase_document before insert or update of document_date on purchase_document for each row execute function opening_date_hard_lock();
drop trigger if exists opening_lock_sales_document on sales_document;create trigger opening_lock_sales_document before insert or update of document_date on sales_document for each row execute function opening_date_hard_lock();
revoke all on function opening_date_hard_lock()from public,anon;notify pgrst,'reload schema';
